(* [comment removed for export] *)
Definition put_at (pc : Z) (ak : Z -> Prop) (p : Z) (cf : config) : Prop :=
  exists (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (s : as_St H) (d : pst) (m : mem) (XS : list (Z * Z)),
    as_VIS H s (cfg_ms cf) = bp_ms pc rax spa gp tp t0 t1 t2 sp a0 a1 a2 a3 a4 a5 a6 a7 E P ff (p1 - p) t3 t4 t5 t6 F fc m
    /\ ak (pc_state (ps_c d))
    /\ as_AKREL H s cf /\ as_MPRES H mo0 (cfg_model cf)
    /\ bput_inv s d m p EC_clear XS.

(* [comment removed for export] *)
Definition put_mid (pc : Z) (stc : pcore -> ecv -> Prop) (p q : Z) (cf : config) : Prop :=
  exists (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (n : Z) (s : as_St H) (d : pst) (m : mem) (E' : ecv) (XS : list (Z * Z)),
    as_VIS H s (cfg_ms cf) = bp_ms pc rax spa gp tp t0 t1 t2 sp a0 a1 a2 a3 a4 a5 a6 a7 E P ff n t3 t4 t5 t6 F fc m
    /\ stc (ps_c d) E'
    /\ as_AKREL H s cf /\ as_MPRES H mo0 (cfg_model cf)
    /\ bput_inv s d m q E' XS
    /\ p0 <= p <= q /\ (E' = EC_clear \/ http_fail E') /\ (E' = EC_clear -> p < q \/ pc_state (ps_c d) = 11)
    /\ (pc_state (ps_c d) = 11 -> E' = EC_clear).

