Definition put_done : config -> Prop :=
  bput_post H MX CX MA MR ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc sE LB0 LF P E lo B shi pad7 pad2 p0 R bs mb d0 m0 mo0.

