Lemma wg_disjoint : forall W A n, Forall wg W -> A + n <= 0x125e40 -> disjoint_from W A n.
Proof.
  open_X.
  intros W A n FW HA. apply disjoint_from_Forall. eapply Forall_impl; [| exact FW]. intros iv WG. left. pose proof (wg_num iv WG) as (K & _). lia.
Qed.
