Lemma wg_sep_W : forall W O n, Forall wg W ->
  fsobj H LF O n -> aapp O n -> 0 <= n ->
  (P + 80 <= O \/ O + n <= P) -> (P + 241 <= O \/ O + n <= P + 240) -> (E + 24 <= O \/ O + n <= E) ->
  disjoint_from W O n /\ disjoint_from W (sh O) (nsh n).
Proof.
  open_X.
  intros W O n FW FO AP N0 S1 S2 S3. split; apply disjoint_from_Forall; (eapply Forall_impl; [| exact FW]); intros iv WG;
    pose proof (wg_sep O n iv FO AP N0 S1 S2 S3 WG) as [K1 K2]; [exact K1| exact K2].
Qed.

