Lemma obj_write_ok : forall s LB m O n l h, as_RHEAP H s (LB ++ LB0) m -> aobj LB0 LF O n -> O <= l -> l <= h -> h <= O + n ->
  aclient_write_ok H (LB ++ LB0) (l, h).
Proof.
  open_X.
  intros s LB m O n l h RH AO H1 H2 H3.
  replace (l, h) with (l, l + (h - l)) by (f_equal; lia).
  assert (AO1 : aobj (LB ++ LB0) LF O n). { eapply aobj_LB_mono; [exact AO|]. intros b Hb; apply in_or_app; right; exact Hb. }
  assert (AO2 : aobj (LB ++ LB0) LF l (h - l)) by (eapply aobj_sub; [exact AO1| lia| lia]).
  exact (proj1 (aobj_write_ok H HH _ _ _ _ _ l (h - l) RH RF0 AO2)).
Qed.

