Lemma keep_rheap : forall W m m' s LB, Forall wg W -> munch W m m' -> wmono asegs m m' ->
  as_RHEAP H s (LB ++ LB0) m -> as_RHEAP H s (LB ++ LB0) m'.
Proof.
  open_X.
  intros W m m' s LB FW MU WM RH. eapply (ah_RHEAP_frame H HH); [exact RH| exact MU| exact WM| exact (wg_write_ok W m s LB FW RH)].
Qed.

Lemma keep_rauxv : forall W m m' s LB mx, Forall wg W -> munch W m m' -> wmono asegs m m' ->
  as_RHEAP H s (LB ++ LB0) mx -> as_rauxv_ok H m B -> as_rauxv_ok H m' B.
Proof.
  open_X.
  intros W m m' s LB mx FW MU WM RH AUX. eapply (ah_rauxv_frame H HH); [exact AUX| exact MU| exact WM| exact (wg_write_ok W mx s LB FW RH)].
Qed.

